def solve(**kwargs):
    import time
    import itertools

    start_time = time.time()
    deadline = start_time + 8.5
    EPS = 1e-9

    stocks = kwargs.get("stocks", [])
    pieces = kwargs.get("pieces", [])
    m = kwargs.get("m", len(pieces))

    if not stocks or not pieces:
        return {"objective": 0.0, "placements": {}}

    # Use the minimum required quantity for each piece type.
    # This is always quantity-feasible and minimizes required used area/complexity.
    items = []
    total_used_area = 0.0
    for i, p in enumerate(pieces):
        q = int(p.get("min", 0))
        if q < 0:
            q = 0
        l = float(p["length"])
        w = float(p["width"])
        area = l * w
        for _ in range(q):
            items.append((i, l, w, area))
        total_used_area += q * area

    if not items:
        return {"objective": 0.0, "placements": {}}

    stock_info = []
    for si, s in enumerate(stocks):
        L = float(s["length"])
        W = float(s["width"])
        stock_info.append((si, L, W, L * W))

    def piece_fits_stock(l, w, L, W):
        return (l <= L + EPS and w <= W + EPS) or (w <= L + EPS and l <= W + EPS)

    # If any required piece cannot fit in any stock, return a harmless empty answer.
    # The instance is infeasible for us otherwise.
    for _, l, w, _ in items:
        ok = False
        for _, L, W, _ in stock_info:
            if piece_fits_stock(l, w, L, W):
                ok = True
                break
        if not ok:
            return {"objective": 0.0, "placements": {}}

    # Candidate stock types: keep the smallest useful types, plus types that are
    # among the best fits for at least one required piece.
    candidate_set = set()
    by_area = sorted(stock_info, key=lambda x: x[3])
    for si, _, _, _ in by_area[:30]:
        candidate_set.add(si)

    unique_piece_dims = {}
    for pi, l, w, area in items:
        unique_piece_dims[(l, w)] = (l, w)

    for l, w in unique_piece_dims.values():
        fitting = []
        for si, L, W, A in stock_info:
            if piece_fits_stock(l, w, L, W):
                fitting.append((A, si))
        fitting.sort()
        for _, si in fitting[:8]:
            candidate_set.add(si)

    candidates = sorted(candidate_set)
    if not candidates:
        return {"objective": 0.0, "placements": {}}

    # Sort items by decreasing area / largest side for first-fit decreasing.
    items_sorted = sorted(
        items,
        key=lambda x: (x[3], max(x[1], x[2]), min(x[1], x[2])),
        reverse=True,
    )

    def try_place_in_bin(bin_obj, l, w):
        L = bin_obj["L"]
        W = bin_obj["W"]
        best = None

        orientations = [(0, l, w)]
        if abs(l - w) > EPS:
            orientations.append((1, w, l))

        for orient, pw, ph in orientations:
            if pw > L + EPS or ph > W + EPS:
                continue

            # Existing shelves.
            for idx, shelf in enumerate(bin_obj["shelves"]):
                if ph <= shelf["h"] + EPS and shelf["used"] + pw <= L + EPS:
                    remaining_x = L - (shelf["used"] + pw)
                    wasted_height = shelf["h"] - ph
                    score = (0, remaining_x, wasted_height)
                    if best is None or score < best[0]:
                        best = (
                            score,
                            {
                                "shelf_index": idx,
                                "new_shelf": False,
                                "x": shelf["used"],
                                "y": shelf["y"],
                                "orientation": orient,
                                "pw": pw,
                                "ph": ph,
                            },
                        )

            # New shelf.
            if bin_obj["height_used"] + ph <= W + EPS:
                remaining_x = L - pw
                remaining_y = W - (bin_obj["height_used"] + ph)
                score = (1, remaining_y, remaining_x)
                if best is None or score < best[0]:
                    best = (
                        score,
                        {
                            "shelf_index": None,
                            "new_shelf": True,
                            "x": 0.0,
                            "y": bin_obj["height_used"],
                            "orientation": orient,
                            "pw": pw,
                            "ph": ph,
                        },
                    )

        return best

    def apply_place(bin_obj, placement_info, piece_index):
        if placement_info["new_shelf"]:
            shelf = {
                "y": placement_info["y"],
                "h": placement_info["ph"],
                "used": placement_info["pw"],
            }
            bin_obj["shelves"].append(shelf)
            bin_obj["height_used"] += placement_info["ph"]
        else:
            shelf = bin_obj["shelves"][placement_info["shelf_index"]]
            shelf["used"] += placement_info["pw"]

        bin_obj["placements"].append(
            {
                "piece": piece_index + 1,
                "x": placement_info["x"],
                "y": placement_info["y"],
                "orientation": placement_info["orientation"],
            }
        )

    def pack_with_stock_set(stock_set):
        bins = []

        for pi, l, w, area in items_sorted:
            if time.time() > deadline:
                return None

            best_choice = None

            # Try existing bins.
            for bi, b in enumerate(bins):
                res = try_place_in_bin(b, l, w)
                if res is not None:
                    score, info = res
                    # Prefer placing in existing bins; tighter fit wins.
                    full_score = (0,) + score + (b["area"],)
                    if best_choice is None or full_score < best_choice[0]:
                        best_choice = (full_score, bi, info)

            if best_choice is not None:
                _, bi, info = best_choice
                apply_place(bins[bi], info, pi)
                continue

            # Open a new bin of one of the allowed stock types.
            best_new = None
            for si in stock_set:
                _, L, W, A = stock_info[si]
                if not piece_fits_stock(l, w, L, W):
                    continue

                temp_bin = {
                    "stock_type": si,
                    "L": L,
                    "W": W,
                    "area": A,
                    "height_used": 0.0,
                    "shelves": [],
                    "placements": [],
                }
                res = try_place_in_bin(temp_bin, l, w)
                if res is None:
                    continue
                score, info = res
                full_score = (A, score)
                if best_new is None or full_score < best_new[0]:
                    best_new = (full_score, temp_bin, info)

            if best_new is None:
                return None

            _, new_bin, info = best_new
            apply_place(new_bin, info, pi)
            bins.append(new_bin)

        total_stock_area = sum(b["area"] for b in bins)
        if total_stock_area <= EPS:
            obj = 0.0
        else:
            obj = max(0.0, (total_stock_area - total_used_area) / total_stock_area)

        return obj, bins

    # Build stock type subsets of size 1 or 2.
    stock_sets = []
    for si in candidates:
        stock_sets.append((si,))
    for a_i in range(len(candidates)):
        for b_i in range(a_i + 1, len(candidates)):
            stock_sets.append((candidates[a_i], candidates[b_i]))

    # Prioritize promising sets with small stock areas.
    stock_sets.sort(key=lambda ss: sum(stock_info[x][3] for x in ss) / len(ss))

    best_obj = None
    best_bins = None

    for ss in stock_sets:
        if time.time() > deadline:
            break

        # Quick coverage check.
        cover_ok = True
        for _, l, w, _ in items_sorted[: min(len(items_sorted), 200)]:
            if not any(piece_fits_stock(l, w, stock_info[si][1], stock_info[si][2]) for si in ss):
                cover_ok = False
                break
        if not cover_ok:
            continue

        result = pack_with_stock_set(ss)
        if result is None:
            continue

        obj, bins = result
        if best_obj is None or obj < best_obj:
            best_obj = obj
            best_bins = bins
            if obj <= EPS:
                break

    # Fallback: one piece per stock using the smallest fitting stock type.
    if best_bins is None:
        bins = []
        allowed_types = set()
        # Pick up to two stock types that cover all pieces greedily.
        for _, l, w, _ in items_sorted:
            fitting = [s for s in stock_info if piece_fits_stock(l, w, s[1], s[2])]
            fitting.sort(key=lambda x: x[3])
            chosen = None
            for s in fitting:
                if s[0] in allowed_types:
                    chosen = s
                    break
            if chosen is None:
                if len(allowed_types) < 2:
                    chosen = fitting[0]
                    allowed_types.add(chosen[0])
                else:
                    chosen = fitting[0]
            si, L, W, A = chosen
            orient = 0
            pw, ph = l, w
            if not (pw <= L + EPS and ph <= W + EPS):
                orient = 1
                pw, ph = w, l
            bins.append(
                {
                    "stock_type": si,
                    "L": L,
                    "W": W,
                    "area": A,
                    "height_used": ph,
                    "shelves": [{"y": 0.0, "h": ph, "used": pw}],
                    "placements": [
                        {
                            "piece": _ + 1 if isinstance(_, int) else 1,
                            "x": 0.0,
                            "y": 0.0,
                            "orientation": orient,
                        }
                    ],
                }
            )

        best_bins = bins
        total_stock_area = sum(b["area"] for b in best_bins)
        best_obj = max(0.0, (total_stock_area - total_used_area) / total_stock_area) if total_stock_area > EPS else 0.0

    placements_out = {}
    for idx, b in enumerate(best_bins, start=1):
        placements_out[idx] = {
            "stock_type": b["stock_type"] + 1,
            "placements": b["placements"],
        }

    return {
        "objective": float(best_obj if best_obj is not None else 0.0),
        "placements": placements_out,
    }
