        if pl <= L + EPS and pw <= W + EPS:
            opts.append((pl, pw, 0))
        if abs(pl - pw) > EPS and pw <= L + EPS and pl <= W + EPS:
            opts.append((pw, pl, 1))
        return opts

    def try_place_in_bin(bin_obj, pidx, stock_L, stock_W):
