                "x": x,
                "y": y,
                "orientation": ori
            })
            bin_obj["used_area"] += rw * rh
            return True

        # Open a new shelf.
        best_new = None
        for rw, rh, ori in opts:
            if bin_obj["next_y"] + rh <= stock_W + EPS:
                rem_x = stock_L - rw
                rem_y = stock_W - (bin_obj["next_y"] + rh)
                score = (rem_y, rem_x)
                if best_new is None or score < best_new[0]:
