        return {
            "objective": 0.0,
            "placements": {}
        }

    # Try packing all minimum-required pieces into each individual stock type.
    for sidx in range(len(stocks)):
        if time.time() > deadline:
            break
        sol = build_solution_for_stock_type(sidx, min_counts)
        if sol is not None:
